        group.MapPost("/production-orders/{orderId:guid}/cost-facts", async (Guid orderId, RecordCostFactRequest request, HttpContext http, ManufacturingRepository repository, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => await Execute(http, await AccessForOrderAsync(http, repository, subjects, authorizer, "manufacturing.cost.manage", orderId, ct), () => repository.RecordCostFactAsync(Tenant(http), Actor(http), orderId, request, ct), StatusCodes.Status201Created));
        group.MapPost("/production-orders/{orderId:guid}/output-cost-allocations", async (Guid orderId, AllocateOutputCostRequest request, HttpContext http, ManufacturingRepository repository, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, CancellationToken ct) => await Execute(http, await AccessForOrderAsync(http, repository, subjects, authorizer, "manufacturing.cost.manage", orderId, ct), () => repository.AllocateOutputCostAsync(Tenant(http), Actor(http), orderId, request, ct), StatusCodes.Status201Created));
        return app;
    }

    private static async Task<Access?> AccessAsync(HttpContext http, IAuthorizationSubjectStore subjects, IPermissionAuthorizer authorizer, string permission, Guid? legalEntityId, CancellationToken ct)
    {
        if (!Guid.TryParse(http.User.FindFirstValue("tenant_id"), out var tenantId) || !Guid.TryParse(http.User.FindFirstValue("membership_id"), out var membershipId) || !Guid.TryParse(http.User.FindFirstValue(ClaimTypes.NameIdentifier), out var actorId)) return null;
        var tenant = new TenantId(tenantId);
        var subject = await subjects.LoadAsync(tenant, membershipId, ct);
        if (subject is null) return null;
        if (legalEntityId is not null && Guid.TryParse(http.User.FindFirstValue("legal_entity_id"), out var claimEntity) && claimEntity != legalEntityId) return new(tenant, actorId, membershipId, false);
        return new(tenant, actorId, membershipId, authorizer.Authorize(subject, permission, legalEntityId is { } entity ? PermissionScope.ForLegalEntity(tenant, new(entity)) : PermissionScope.ForTenant(tenant)));
    }

